const DISK_R = 22;

/* -------------------------- helpers --------------------------------- */

// 带切角(倒角)矩形外轮廓 —— CCW 绕行 (Shape 坐标系: x=X, y=Z)
function chamferedRectShape(w, d, c) {
  const s = new THREE.Shape();
  const hw = w / 2, hd = d / 2;
  s.moveTo(-hw + c, -hd);
  s.lineTo( hw - c, -hd);
  s.lineTo( hw, -hd + c);
  s.lineTo( hw,  hd - c);
  s.lineTo( hw - c,  hd);
  s.lineTo(-hw + c,  hd);
  s.lineTo(-hw,  hd - c);
  s.lineTo(-hw, -hd + c);
  s.closePath();
