}

// 普通矩形 (CCW)
function rectShape(w, d) {
  const s = new THREE.Shape();
  const hw = w / 2, hd = d / 2;
  s.moveTo(-hw, -hd);
  s.lineTo( hw, -hd);
  s.lineTo( hw,  hd);
