import * as THREE from 'three';

const HEAD_CHANNEL = { x: -8, z: 22, w: 6, d: 14 };
const SHELL_W = 60, SHELL_D = 60, SHELL_T = 2, CHAMFER = 3;
const LINER_OUTER = 24, LINER_INNER = 9;
const LINER_NOTCH_ANGLE = Math.PI * 112 / 180;
const LINER_NOTCH_HALF = Math.PI * 15 / 180;

function chamferedRectShape(w, d, c) {
  const s = new THREE.Shape();
  const hw = w / 2, hd = d / 2;
  s.moveTo(-hw + c, -hd); s.lineTo( hw - c, -hd); s.lineTo( hw, -hd + c);
  s.lineTo( hw,  hd - c); s.lineTo( hw - c,  hd); s.lineTo(-hw + c,  hd);
  s.lineTo(-hw,  hd - c); s.lineTo(-hw, -hd + c); s.closePath();
  return s;
}
function rectShape(w, d) {
  const s = new THREE.Shape();
  const hw = w / 2, hd = d / 2;
  s.moveTo(-hw, -hd); s.lineTo( hw, -hd); s.lineTo( hw,  hd); s.lineTo(-hw,  hd); s.closePath();
  return s;
}
function rectHolePath(cx, cy, w, d) {
  const p = new THREE.Path();
  const hw = w / 2, hd = d / 2;
  p.moveTo(cx - hw, cy - hd); p.lineTo(cx - hw, cy + hd);
  p.lineTo(cx + hw, cy + hd); p.lineTo(cx + hw, cy - hd); p.closePath();
  return p;
}
function circleHolePath(cx, cy, r, segments = 48) {
  const p = new THREE.Path();
  p.absarc(cx, cy, r, 0, Math.PI * 2, true);
  return p;
}
function plateGeo(shape, thickness) {
  const geo = new THREE.ExtrudeGeometry(shape, { depth: thickness, bevelEnabled: false, curveSegments: 32 });
  geo.rotateX(Math.PI / 2);
  geo.translate(0, thickness, 0);
  geo.translate(0, -thickness / 2, 0);
  return geo;
}
function check(name, geo) {
  const pos = geo.getAttribute('position');
  const arr = pos.array;
  let nan = 0, inf = 0;
  for (let i = 0; i < arr.length; i++) {
    if (Number.isNaN(arr[i])) nan++;
    else if (!Number.isFinite(arr[i])) inf++;
  }
  const area = geo.getAttribute('position').count / 3; // tris*3
  console.log(`${name}: vertices=${pos.count} tris=${pos.count/3} NaN=${nan} Inf=${inf} bbox=[${geo.boundingBox ? geo.boundingBox.min.toArray().map(n=>n.toFixed(1)) : '?'}]`);
  geo.computeBoundingBox();
  console.log(`   bbox min=[${geo.boundingBox.min.toArray().map(n=>n.toFixed(2))}] max=[${geo.boundingBox.max.toArray().map(n=>n.toFixed(2))}]`);
}

// Top shell
const top = chamferedRectShape(SHELL_W, SHELL_D, CHAMFER);
top.holes.push(rectHolePath(-26, -26, 4, 4));
top.holes.push(rectHolePath(HEAD_CHANNEL.x, HEAD_CHANNEL.z, HEAD_CHANNEL.w, HEAD_CHANNEL.d));
check('TOP SHELL', plateGeo(top, SHELL_T));

// Bottom shell
const bot = chamferedRectShape(SHELL_W, SHELL_D, CHAMFER);
bot.holes.push(circleHolePath(0, 0, 7));
bot.holes.push(rectHolePath(26, -26, 3, 3));
bot.holes.push(rectHolePath(HEAD_CHANNEL.x, HEAD_CHANNEL.z, HEAD_CHANNEL.w, HEAD_CHANNEL.d));
check('BOTTOM SHELL', plateGeo(bot, SHELL_T));

// Depression annulus
const dep = new THREE.Shape();
dep.absarc(0, 0, 22, 0, Math.PI * 2, false);
dep.holes.push(circleHolePath(0, 0, 7));
check('DEPRESSION', plateGeo(dep, 0.06));

// Liner C-shape
const s = new THREE.Shape();
const a0 = LINER_NOTCH_ANGLE + LINER_NOTCH_HALF;
const a1 = LINER_NOTCH_ANGLE - LINER_NOTCH_HALF + Math.PI * 2;
s.absarc(0, 0, LINER_OUTER, a0, a1, false);
s.lineTo(LINER_INNER * Math.cos(a1), LINER_INNER * Math.sin(a1));
s.absarc(0, 0, LINER_INNER, a1, a0, true);
s.lineTo(LINER_OUTER * Math.cos(a0), LINER_OUTER * Math.sin(a0));
s.closePath();
check('DUST LINER', plateGeo(s, 0.1));

// Shutter
const sh = rectShape(22, 16);
sh.holes.push(rectHolePath(-3, -0.5, HEAD_CHANNEL.w, HEAD_CHANNEL.d));
check('SHUTTER', plateGeo(sh, 1));

console.log('ALL GEOMETRY OK');
EOF
